        result.add(list);
    } while (nextPerm(arr));
    return result;
}
private boolean nextPerm(int[] a) {
    int i = a.length - 2;
    while (i >= 0 && a[i] >= a[i+1]) i--;
    if (i < 0) return false;
    int j = a.length - 1;
    while (a[j] <= a[i]) j--;
    swap(a,i,j);
    int left = i+1, right = a.length-1;
    while (left < right) {
        swap(a,left,right);
        left++; right--;
    }
    return true;
}
private void swap(int[] a, int i, int j){ int tmp = a[i]; a[i]=a[j]; a[j]=tmp;}

