        result.append(key);
        decrementKey(freq,key);
        char last = key;
        while (true) {
            Character next = freq.higherKey(last);
            if (next == null) break;
            result.append(next);
            decrementKey(freq,next);
            last = next;
        }
        // descending phase
        if (freq.isEmpty()) break; // nothing left
